package ama.transcript;
import java.sql.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.SingleConnectionDataSource;import static org.junit.jupiter.api.Assertions.*;
/** Real two-connection COUNT/SELECT interleaving against bounded test-only metadata, no business rows. */
public final class Task11Fix02MetadataGrowthProbe {
 public static Map<String,Object> verify(DataSource source)throws Exception {
  try(var reader=source.getConnection();var writer=source.getConnection()){
   assertNotSame(reader.unwrap(Connection.class),writer.unwrap(Connection.class));assertTrue(reader.getAutoCommit());assertTrue(writer.getAutoCommit());var before=new JdbcTemplate(new SingleConnectionDataSource(reader,true));assertEquals(0,before.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='fix02_publication_metadata_growth'",Integer.class));
   before.execute("CREATE TABLE fix02_publication_metadata_growth (id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY) ENGINE=InnoDB");assertEquals(1,before.update("INSERT INTO fix02_publication_metadata_growth(id) VALUES ('row-0001')"));
   var read=new ama.contract.ConfigArchiveContracts.ArchiveReadBudget(65536,10000000,100,100,16,100000,16,128,65536,65536,10000000,65536,1000,10000,100000);var canonical=new ama.contract.MinutesContracts.CanonicalBudget(10000000,32,100000,65536,100000);var budget=new TranscriptAcquisitionBudget(10000000,10000000,10000000,100000000,100000000,1000000,16,256,256).ledger(read,canonical,()->false);var trace=new ArrayList<Map<String,Object>>();
   var jdbc=new JdbcTemplate(new SingleConnectionDataSource(reader,true)){
    @Override public <T>T queryForObject(String sql,Class<T> type,Object... args){T count=super.queryForObject(sql,type,args);assertEquals(1L,count);try(var statement=writer.createStatement()){assertEquals(3,statement.executeUpdate("INSERT INTO fix02_publication_metadata_growth(id) VALUES ('row-0002'),('row-0003'),('row-0004')"));}catch(SQLException failure){throw new IllegalStateException(failure);}trace.add(Map.of("phase","after-count-before-select","count",count,"insertedBySecondConnection",3));return count;}
    @Override public List<Map<String,Object>> queryForList(String sql,Object... args){long reserved=budget.usage()[5];var rows=super.queryForList(sql,args);trace.add(Map.of("phase","select","sql",sql,"rowsTransferred",rows.size(),"rowsAdmittedBeforeExecute",reserved));assertTrue(rows.size()<=reserved,"JDBC transferred unreserved rows");return rows;}
   };
   var method=PublicationGraph.class.getDeclaredMethod("read",JdbcTemplate.class,MinutesPendingDiscovery.Query.class,boolean.class,TranscriptAcquisitionBudget.Ledger.class);method.setAccessible(true);var query=new MinutesPendingDiscovery.Query("fix02_publication_metadata_growth",List.of("id"),List.of("id"),"id>=?",List.of("row-0001"));var failure=assertThrows(java.lang.reflect.InvocationTargetException.class,()->method.invoke(null,jdbc,query,false,budget));assertInstanceOf(ama.contract.MinutesContracts.Failure.class,failure.getCause());assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,((ama.contract.MinutesContracts.Failure)failure.getCause()).code());assertEquals(4,before.queryForObject("SELECT COUNT(*) FROM fix02_publication_metadata_growth",Integer.class));assertEquals(2L,budget.usage()[5]);
   return Map.of("trace",trace,"rowsRetained",4,"actualFailure","PROVENANCE_UNAVAILABLE","qualification","real production PublicationGraph.read SQL/ledger; independent autocommit writer inserts3 between COUNT1 and SELECT; separate test-only table, no publication/task business rows; table retained as evidence");
  }
 }
}
